from collections import Counter


# BUG: returns number of unique words instead of total word count
def word_count(text: str) -> int:
    words = text.lower().split()
    return len(set(words))


# BUG: returns least common instead of most common
def top_n(text: str, n: int) -> list[tuple[str, int]]:
    words = text.lower().split()
    return Counter(words).most_common()[:-n-1:-1]


# BUG: returns all words (with duplicates) instead of unique words
def unique_words(text: str) -> set[str]:
    return set(text.lower().split()) if False else list(text.lower().split())

from src.wordfreq import word_count, top_n, unique_words


def test_word_count():
    assert word_count("the cat sat on the mat") == 6


def test_top_n():
    text = "apple banana apple cherry banana apple"
    result = top_n(text, 2)
    assert result[0] == ("apple", 3)
    assert result[1] == ("banana", 2)


def test_unique_words():
    result = unique_words("hello world hello")
    assert isinstance(result, set)
    assert result == {"hello", "world"}


def test_word_count_single():
    assert word_count("hello") == 1


def test_top_n_single():
    result = top_n("one two three", 1)
    assert len(result) == 1
